def countPaths(n, edges):
    from collections import defaultdict

    # Sieve of primes up to n
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Union-Find over non-prime nodes (only merging edges where both ends are non-prime)
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    for u, v in edges:
        if not is_prime[u] and not is_prime[v]:
            union(u, v)

    answer = 0
    # For each prime node, its non-prime neighbors each lead to a distinct
    # non-prime component (a "branch"). A valid path through this prime uses
    # the prime plus nodes from at most two distinct branches.
    for p in range(1, n + 1):
        if not is_prime[p]:
            continue
        branches = []
        for nb in adj[p]:
            if not is_prime[nb]:
                branches.append(size[find(nb)])
        s = 0  # running sum of previous branch sizes
        for b in branches:
            # pairs crossing through p between this branch and all previous ones
            answer += s * b
            # path with p as one endpoint and a node in this branch as the other
            answer += b
            s += b
    return answer
